package com.example.contract.entity;

import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * Contract entity representing a property lease agreement.
 */
public class Contract {
    private Long id;
    private String contractNo;
    private String tenantName;
    private String tenantId;
    private String propertyAddress;
    private String propertyType;      // OFFICE, RETAIL, WAREHOUSE
    private BigDecimal area;           // square meters
    private BigDecimal monthlyRent;
    private BigDecimal deposit;
    private BigDecimal totalValue;
    private LocalDate startDate;
    private LocalDate endDate;
    private int billingCycleMonths;    // 1=monthly, 3=quarterly, 6=semi-annual
    private String status;             // DRAFT, ACTIVE, ARCHIVED, TERMINATED
    private String originalContractNo; // for modified contracts
    private String modifiedContractNo; // points to replacement contract
    private LocalDate createTime;
    private LocalDate terminationDate;
    private BigDecimal terminationPenalty;

    // Getters and setters
    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }
    public String getContractNo() { return contractNo; }
    public void setContractNo(String contractNo) { this.contractNo = contractNo; }
    public String getTenantName() { return tenantName; }
    public void setTenantName(String tenantName) { this.tenantName = tenantName; }
    public String getTenantId() { return tenantId; }
    public void setTenantId(String tenantId) { this.tenantId = tenantId; }
    public String getPropertyAddress() { return propertyAddress; }
    public void setPropertyAddress(String propertyAddress) { this.propertyAddress = propertyAddress; }
    public String getPropertyType() { return propertyType; }
    public void setPropertyType(String propertyType) { this.propertyType = propertyType; }
    public BigDecimal getArea() { return area; }
    public void setArea(BigDecimal area) { this.area = area; }
    public BigDecimal getMonthlyRent() { return monthlyRent; }
    public void setMonthlyRent(BigDecimal monthlyRent) { this.monthlyRent = monthlyRent; }
    public BigDecimal getDeposit() { return deposit; }
    public void setDeposit(BigDecimal deposit) { this.deposit = deposit; }
    public BigDecimal getTotalValue() { return totalValue; }
    public void setTotalValue(BigDecimal totalValue) { this.totalValue = totalValue; }
    public LocalDate getStartDate() { return startDate; }
    public void setStartDate(LocalDate startDate) { this.startDate = startDate; }
    public LocalDate getEndDate() { return endDate; }
    public void setEndDate(LocalDate endDate) { this.endDate = endDate; }
    public int getBillingCycleMonths() { return billingCycleMonths; }
    public void setBillingCycleMonths(int billingCycleMonths) { this.billingCycleMonths = billingCycleMonths; }
    public String getStatus() { return status; }
    public void setStatus(String status) { this.status = status; }
    public String getOriginalContractNo() { return originalContractNo; }
    public void setOriginalContractNo(String originalContractNo) { this.originalContractNo = originalContractNo; }
    public String getModifiedContractNo() { return modifiedContractNo; }
    public void setModifiedContractNo(String modifiedContractNo) { this.modifiedContractNo = modifiedContractNo; }
    public LocalDate getCreateTime() { return createTime; }
    public void setCreateTime(LocalDate createTime) { this.createTime = createTime; }
    public LocalDate getTerminationDate() { return terminationDate; }
    public void setTerminationDate(LocalDate terminationDate) { this.terminationDate = terminationDate; }
    public BigDecimal getTerminationPenalty() { return terminationPenalty; }
    public void setTerminationPenalty(BigDecimal terminationPenalty) { this.terminationPenalty = terminationPenalty; }
}

package com.example.contract.controller;

import com.example.contract.entity.Contract;
import com.example.contract.entity.ContractDetail;
import com.example.contract.service.ContractService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.bind.annotation.*;

import java.util.List;
import java.util.Map;

/**
 * Contract management controller.
 * Handles CRUD operations for property lease contracts.
 */
@RestController
@RequestMapping("/api/contracts")
public class ContractController {

    @Autowired
    private ContractService contractService;

    @PostMapping("/create")
    public Map<String, Object> createContract(@RequestBody Contract contract) {
        contractService.initializeContract(contract);
        contractService.calculateSettlementPeriods(contract);
        return Map.of("success", true, "contractId", contract.getId());
    }

    @PostMapping("/{id}/modify")
    public Map<String, Object> modifyContract(
            @PathVariable Long id,
            @RequestBody Contract modifiedContract) {
        Contract original = contractService.getById(id);
        contractService.validateModification(original, modifiedContract);
        contractService.executeModification(original, modifiedContract);
        return Map.of("success", true);
    }

    @GetMapping("/{id}")
    public Contract getContract(@PathVariable Long id) {
        return contractService.getById(id);
    }

    @GetMapping("/{id}/details")
    public List<ContractDetail> getContractDetails(@PathVariable Long id) {
        return contractService.getContractDetails(id);
    }

    @PostMapping("/{id}/terminate")
    public Map<String, Object> terminateContract(@PathVariable Long id) {
        contractService.terminateContract(id);
        return Map.of("success", true);
    }

    @GetMapping("/search")
    public List<Contract> searchContracts(
            @RequestParam(required = false) String keyword,
            @RequestParam(required = false) String status,
            @RequestParam(defaultValue = "1") int page,
            @RequestParam(defaultValue = "20") int size) {
        return contractService.searchContracts(keyword, status, page, size);
    }
}

package com.example.contract.service;

import com.example.contract.entity.Contract;
import com.example.contract.entity.ContractDetail;
import com.example.contract.entity.SettlementPeriod;

import java.util.List;

/**
 * Core service for contract lifecycle management.
 */
public interface ContractService {

    /**
     * Initialize a new contract with default values and calculate initial financial data.
     * Steps: validate input -> generate contract number -> set status to DRAFT
     *        -> calculate initial rent schedule -> persist.
     */
    void initializeContract(Contract contract);

    /**
     * Calculate settlement periods based on contract start/end dates and billing cycle.
     * Generates a list of SettlementPeriod records covering the full contract term.
     */
    void calculateSettlementPeriods(Contract contract);

    /**
     * Validate that a contract modification is allowed.
     * Checks: contract is in ACTIVE status, modification date is valid,
     *         financial impact is within approval limits.
     */
    void validateModification(Contract original, Contract modified);

    /**
     * Execute the modification: archive old contract, create new version,
     * recalculate settlement periods, adjust accounting entries.
     */
    void executeModification(Contract original, Contract modified);

    /**
     * Retrieve contract by ID with full details.
     */
    Contract getById(Long id);

    /**
     * Get all detail line items for a contract.
     */
    List<ContractDetail> getContractDetails(Long id);

    /**
     * Terminate contract early. Calculates penalty, adjusts remaining periods,
     * creates final settlement record.
     */
    void terminateContract(Long id);

    /**
     * Search contracts by keyword (contract number, tenant name) and status.
     */
    List<Contract> searchContracts(String keyword, String status, int page, int size);
}

package com.example.contract.service.impl;

import com.example.contract.dao.ContractDao;
import com.example.contract.dao.SettlementPeriodDao;
import com.example.contract.entity.Contract;
import com.example.contract.entity.ContractDetail;
import com.example.contract.entity.SettlementPeriod;
import com.example.contract.service.ContractService;
import com.example.contract.service.FinancialCalculationService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

@Service
public class ContractServiceImpl implements ContractService {

    @Autowired
    private ContractDao contractDao;

    @Autowired
    private SettlementPeriodDao settlementPeriodDao;

    @Autowired
    private FinancialCalculationService financialCalcService;

    @Override
    @Transactional
    public void initializeContract(Contract contract) {
        contract.setContractNo("CT-" + UUID.randomUUID().toString().substring(0, 8).toUpperCase());
        contract.setStatus("DRAFT");
        contract.setCreateTime(LocalDate.now());

        // Calculate total contract value
        BigDecimal monthlyRent = contract.getMonthlyRent();
        long months = ChronoUnit.MONTHS.between(contract.getStartDate(), contract.getEndDate());
        contract.setTotalValue(monthlyRent.multiply(BigDecimal.valueOf(months)));

        // Calculate deposit (typically 3 months rent)
        contract.setDeposit(monthlyRent.multiply(BigDecimal.valueOf(3)));

        contractDao.insert(contract);
    }

    @Override
    @Transactional
    public void calculateSettlementPeriods(Contract contract) {
        List<SettlementPeriod> periods = new ArrayList<>();
        LocalDate current = contract.getStartDate();
        int seq = 1;

        while (current.isBefore(contract.getEndDate())) {
            LocalDate periodEnd = current.plusMonths(contract.getBillingCycleMonths());
            if (periodEnd.isAfter(contract.getEndDate())) {
                periodEnd = contract.getEndDate();
            }

            SettlementPeriod period = new SettlementPeriod();
            period.setContractId(contract.getId());
            period.setSequence(seq++);
            period.setStartDate(current);
            period.setEndDate(periodEnd);

            // Pro-rate if partial period
            long totalDays = ChronoUnit.DAYS.between(current, periodEnd);
            long fullMonthDays = ChronoUnit.DAYS.between(current, current.plusMonths(contract.getBillingCycleMonths()));
            BigDecimal ratio = BigDecimal.valueOf(totalDays)
                    .divide(BigDecimal.valueOf(fullMonthDays), 6, RoundingMode.HALF_UP);
            BigDecimal periodAmount = contract.getMonthlyRent()
                    .multiply(BigDecimal.valueOf(contract.getBillingCycleMonths()))
                    .multiply(ratio);
            period.setAmount(periodAmount.setScale(2, RoundingMode.HALF_UP));
            period.setStatus("PENDING");

            periods.add(period);
            current = periodEnd;
        }

        settlementPeriodDao.batchInsert(periods);
    }

    @Override
    public void validateModification(Contract original, Contract modified) {
        if (!"ACTIVE".equals(original.getStatus())) {
            throw new IllegalStateException("Only ACTIVE contracts can be modified");
        }
        if (modified.getStartDate().isBefore(LocalDate.now())) {
            throw new IllegalArgumentException("Modification start date cannot be in the past");
        }
        // Check financial impact threshold
        BigDecimal impact = financialCalcService.calculateModificationImpact(original, modified);
        if (impact.abs().compareTo(new BigDecimal("100000")) > 0) {
            throw new IllegalStateException("Modification exceeds approval limit, requires VP approval");
        }
    }

    @Override
    @Transactional
    public void executeModification(Contract original, Contract modified) {
        // Archive original
        original.setStatus("ARCHIVED");
        original.setModifiedContractNo(modified.getContractNo());
        contractDao.update(original);

        // Delete remaining unpaid settlement periods
        settlementPeriodDao.deleteUnpaidByContractId(original.getId());

        // Create new contract version
        modified.setContractNo(original.getContractNo() + "-MOD-" + LocalDate.now());
        modified.setStatus("ACTIVE");
        modified.setOriginalContractNo(original.getContractNo());
        contractDao.insert(modified);

        // Recalculate settlement periods for new contract
        calculateSettlementPeriods(modified);

        // Create accounting adjustment entries
        financialCalcService.createModificationAdjustments(original, modified);
    }

    @Override
    public Contract getById(Long id) {
        return contractDao.selectById(id);
    }

    @Override
    public List<ContractDetail> getContractDetails(Long id) {
        return contractDao.selectDetailsByContractId(id);
    }

    @Override
    @Transactional
    public void terminateContract(Long id) {
        Contract contract = contractDao.selectById(id);
        if (contract == null) {
            throw new IllegalArgumentException("Contract not found: " + id);
        }

        // Calculate early termination penalty (remaining rent * penalty rate)
        BigDecimal penalty = financialCalcService.calculateTerminationPenalty(contract);

        // Update contract status
        contract.setStatus("TERMINATED");
        contract.setTerminationDate(LocalDate.now());
        contract.setTerminationPenalty(penalty);
        contractDao.update(contract);

        // Cancel remaining settlement periods
        settlementPeriodDao.cancelRemainingByContractId(id);

        // Create final settlement record
        financialCalcService.createTerminationSettlement(contract, penalty);
    }

    @Override
    public List<Contract> searchContracts(String keyword, String status, int page, int size) {
        int offset = (page - 1) * size;
        return contractDao.search(keyword, status, offset, size);
    }
}
